import { test, expect } from '@playwright/test';

test.describe('User Login with Valid Credentials', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/login');
  });

  test('should successfully log in with valid credentials and navigate to dashboard', async ({ page }) => {
    // Verify login page is visible
    const loginPage = page.getByRole('main');
    await expect(loginPage).toBeVisible();

    // Locate and fill email input using getByLabel
    const emailInput = page.getByLabel('Email Address');
    await expect(emailInput).toBeVisible();
    await emailInput.fill('user@example.com');

    // Locate and fill password input using getByLabel
    const passwordInput = page.getByLabel('Password');
    await expect(passwordInput).toBeVisible();
    await passwordInput.fill('ValidPassword123');

    // Locate and click login button using getByRole
    const loginButton = page.getByRole('button', { name: /log in/i });
    await expect(loginButton).toBeVisible();
    await loginButton.click();

    // Wait for navigation to dashboard
    await page.waitForURL('**/dashboard');

    // Verify dashboard page is loaded
    const dashboardPage = page.getByRole('main');
    await expect(dashboardPage).toBeVisible();

    // Verify welcome message is displayed
    const welcomeMessage = page.getByText(/welcome back/i);
    await expect(welcomeMessage).toBeVisible();

    // Verify user profile icon is visible
    const profileIcon = page.getByRole('img', { name: /profile/i });
    await expect(profileIcon).toBeVisible();

    // Verify user is logged in by checking for dashboard content
    const dashboardContent = page.getByText(/your dashboard/i);
    await expect(dashboardContent).toBeVisible();
  });

  test('should display error message when login fails with invalid password', async ({ page }) => {
    // Locate and fill email input using getByLabel
    const emailInput = page.getByLabel('Email Address');
    await expect(emailInput).toBeVisible();
    await emailInput.fill('user@example.example.com');

    // Locate and fill password input with invalid password using getByLabel
    const passwordInput = page.getByLabel('Password');
    await expect(passwordInput).toBeVisible();
    await passwordInput.fill('WrongPassword123');

    // Locate and click login button using getByRole
    const loginButton = page.getByRole('button', { name: /log in/i });
    await expect(loginButton).toBeVisible();
    await loginButton.click();

    // Wait for error message to appear
    await page.waitForTimeout(500);

    // Verify error message is displayed
    const errorMessage = page.getByText(/invalid credentials/i);
    await expect(errorMessage).toBeVisible();

    // Verify user remains on login page
    const loginPage = page.getByRole('main');
    await expect(loginPage).toBeVisible();

    // Verify login button is still visible for retry
    await expect(loginButton).toBeVisible();

    // Verify email input still contains value
    await expect(emailInput).toHaveValue('user@example.com');
  });
});
